import React, { useState } from 'react';
import Card from './components/card/Card';
import Input from './components/input/Input';
import TodoItem from './components/todo-item/TodoItem';
import TextArea from './components/input/TextArea';
import Button from './components/button/Button';
import Modal from './components/modal/Modal';

import './App.css';

const TODOS_MOCK = [
  {
    id: '1',
    title: 'Todo 1',
    description:
      'Lorem ipsum dolor sit amet consectetur adipisicing elit. At id illo repellendus non maiores in pariatur aliquam iure fugit amet!',
    completed: false,
  },
  {
    id: '2',
    title: 'Todo 2',
    description: 'Lorem ipsum dolor sit amet consectetur adipisicing elit!',
    completed: false,
  },
  {
    id: '3',
    title: 'Todo 3',
    description: 'Lorem ipsum dolor sit amet consectetur adipisicing elit!',
    completed: true,
  },
  {
    id: '4',
    title: 'Todo 4',
    description: 'Lorem ipsum dolor sit amet consectetur adipisicing elit!',
    completed: true,
  },
];

function App() {
  const [todos, setTodos] = useState(TODOS_MOCK);
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);

  const handleCreateTodo = (e) => {
    e.preventDefault();
    const newTodo = {
      id: todos.length + 1,
      title,
      description,
      completed: false,
    };
    setTodos([...todos, newTodo]);
    setTitle('');
    setDescription('');
    setIsModalOpen(false);
  };
  return (
    <div className='App'>
      <div className='app-container'>
        {/* 
            This is your Create Card component.
          */}
        <Modal>
          <Card>
            <h2>Create Todo</h2>
            <form>
              <Input onChange={() => {}} placeholder='Title' type='text' />
              <TextArea onChange={() => {}} placeholder='Description' />
              <Button type='submit'>Create</Button>
            </form>
          </Card>
        </Modal>

        {/* 
          My Todos
        */}
        <Card>
          <h1>My todos</h1>
          <Button onClick={() => console.log('Open Modal')}>Add +</Button>
          <div className='list-container'>
            <TodoItem todos={todos.filter((todo) => !todo.completed)} />
          </div>

          <div className='separator'></div>

          <h2>Completed</h2>
          <div className='list-container'>
            <TodoItem todos={todos.filter((todo) => todo.completed)} />
          </div>
        </Card>
      </div>
    </div>
  );
}

export default App;
